          stats.pagesSkipped++;
          const perPageTimeMs = 10;
          stats.timeSavedMs += perPageTimeMs;
          continue;
        }
      }

      let page: PageData = {
        slug,
        frontmatter: { title: slug, date: '', tags: [] },
