          slug,
          contentHash,
          templateHash,
          html: page.html,
          frontmatter: page.frontmatter,
        };
        cache.setEntry(entry);
      }
    }

    if (isIncremental) {
      cache.save();
    }

    if (cachedHtmlMap.size > 0) {
      ctx.cachedPages = cachedHtmlMap;
    }

    await this.runHook('afterBuild', ctx);
    await this.runHook('onEnd', ctx);

