    if (isIncremental && stats.pagesSkipped > 0) {
      console.log(
        `[ssg] Built ${stats.pagesBuilt} page(s), skipped ${stats.pagesSkipped} page(s) unchanged, saved ~${stats.timeSavedMs}ms`
      );
    }

    return stats;
  }

