title: Post B
date: 2024-02-01
---
# B v2`);

    const stats2 = await engine.build({ contentDir, outputDir: dist, templatesDir: dist, incremental: true });
    expect(stats2.pagesBuilt).toBe(1);
    expect(stats2.pagesSkipped).toBe(1);

